const originalShowNotification=self.registration.showNotification.bind(self.registration);self.registration.showNotification=(title,options={})=>originalShowNotification(title,{...options,silent:false,vibrate:[180,80,180],...(options.tag?{renotify:true}:{})});
/* Firebase config must belong to the same project as the server sender. */
importScripts('https://www.gstatic.com/firebasejs/11.10.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/11.10.0/firebase-messaging-compat.js');
self.addEventListener('notificationclick',event=>{event.notification.close();const data=event.notification.data?.FCM_MSG?.data||event.notification.data||{};event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(windows=>{const target=windows.find(w=>w.url.startsWith(self.registration.scope));if(target){target.postMessage({type:'tkt-notice-click',id:data.notification_id});return target.focus();}const url=new URL(self.registration.scope);if(data.notification_id)url.searchParams.set('notice',data.notification_id);return clients.openWindow(url.href);}));});
fetch('./firebase-config.json').then(r=>r.ok?r.json():null).then(config=>{if(config?.apiKey){firebase.initializeApp(config);firebase.messaging();}});

self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.mode==='navigate'&&url.origin===self.location.origin&&url.pathname===new URL(self.registration.scope).pathname)event.respondWith(fetch(event.request).catch(()=>new Response('<!doctype html><html lang="ar" dir="rtl"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إدارة تكتوكة</title><body style="font-family:Arial;text-align:center;padding:60px 24px;background:#f5f7fb;color:#142642"><h1>تحتاج اتصال بالإنترنت</h1><p>شغّل الإنترنت حتى تعرض بيانات الداشبورد الحالية.</p><button onclick="location.reload()" style="background:#d90036;color:white;border:0;border-radius:12px;padding:16px 30px;font-size:18px">حاول مرة ثانية</button></body></html>',{headers:{'Content-Type':'text/html; charset=utf-8'}})));});
